#!/usr/bin/env bash
# Deploy the upstream federated-learning-controller (pinned commit, official
# image pinned by digest) into open-cluster-management on the hub.
# Equivalent to the upstream `make deploy`, without needing Go/controller-gen.
source "$(dirname "$0")/lib.sh"

overlay="$UPSTREAM_DIR/federated-learning-controller/config/ocm-demo"
mkdir -p "$overlay"
cat > "$overlay/kustomization.yaml" <<EOF
# Generated by infra/scripts/50-fl-controller.sh
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
namespace: open-cluster-management
resources:
  - ../default
images:
  - name: controller
    newName: $FL_CONTROLLER_IMAGE
    digest: $FL_CONTROLLER_DIGEST
EOF

log "Deploying the federated-learning-controller"
kc apply -k "$overlay"
kc -n open-cluster-management rollout status deploy -l control-plane=controller-manager --timeout=180s
kc get crd federatedlearnings.federation-ai.open-cluster-management.io
